def _has_positional_indexing(self):
    """Check if any column specifier is positional.

    Returns
    -------
    bool
    """
    for col in self._columns:
        # Strings are named columns
        if isinstance(col, str):
            continue
        # List of strings are named columns
        if isinstance(col, list) and all(isinstance(x, str) for x in col):
            continue
        # Positional indices
        if isinstance(col, (int, slice)):
            return True
        # Boolean mask arrays or integer arrays
        if hasattr(col, 'dtype'):
            if np.issubdtype(col.dtype, np.bool_):
                return True
            if np.issubdtype(col.dtype, np.integer):
                return True
    return False

