    """Return a picklable representation of this ResolverMatch.

    ResolveMatch holds a reference to a callback function which may not be
    pickleable, e.g. a view returned by View.as_view() or a function that
    has been dynamically constructed. In those cases attempting to pickle
    the object will raise an exception.  To allow pickling we replace the
    callback with information needed to reconstruct it.
    """
    state = self.__dict__.copy()
    func = state.get('func')
    if func is not None:
        # Determine how to reconstruct the function.
        if hasattr(func, 'view_class'):
            # Class based view (returned from View.as_view()).
            state['_func_reconstruct'] = ('cbv', func.view_class, func.view_initkwargs)
        elif hasattr(func, '__module__') and hasattr(func, '__name__'):
            # Function based view.
            state['_func_reconstruct'] = ('fbv', func.__module__, func.__name__)
        else:
            # Unknown type, leave it unpickleable
            state['_func_reconstruct'] = ('unknown', None, None)
        # Remove the raw function from the state.
        del state['func']
    return state

def __setstate__(self, state):
    """Restore a ResolverMatch from a pickled representation.

    The function reference is recreated from the information stored in
    ``_func_reconstruct`` during pickling.
    """
    reconstruct = state.pop('_func_reconstruct', None)
    if reconstruct:
        kind = reconstruct[0]
        if kind == 'cbv':
